7		"kena.bot/api-db-go/internal/domain/dbauditlog"
8		apierrors "kena.bot/api-db-go/internal/domain/errors"
9	)
10	
11	// Request DTOs + parsers for el router `/audit-log`. Vertical SIN
12	// contrapartida en el Node api-db (el registro de actividad del panel es
13	// nuevo), así que no hay un zod que mirrorear byte a byte. Se mantiene la
14	// MISMA forma de fallo que el resto del servicio (400 estructurado, contexto
15	// ZOD, primer campo que falla vía `zodItemError`) y se reutilizan los
16	// helpers compartidos del paquete: zodItemError, parseRequiredString,
17	// parseNullableBoundedString, parseEnumRequired, isJSONNull, jsonKind,
18	// bodyBindError, coerceLimit, coerceOffset — igual que
19	// moderation_flow_runs_validations.go.
20	
21	// auditLogStatusSet + auditLogStatusMsg — el enum cerrado de `status`, mismo
22	// estilo "Invalid option" del resto (p.ej. flowRunStatusMsg). Construido a
23	// partir de las constantes de dbauditlog (no de `Statuses`, para que el
24	// `map[string]bool` que piden parseEnumRequired/el filtro de listado quede
25	// como literal, igual que flowRunStatusSet).
26	var auditLogStatusSet = map[string]bool{
27		dbauditlog.StatusOK:    true,
28		dbauditlog.StatusError: true,
29	}
30	
31	const auditLogStatusMsg = `Invalid option: expected one of "ok"|"error"`
32	
33	// auditLogChangesMaxBytes es el techo de tamaño serializado que
34	// ParseAuditLogCreate exige a `changes`: un documento libre, pero no
35	// ilimitado — un blob enorme inflaría silenciosamente la colección (y la
36	// poda por servidor, que cuenta FILAS, no bytes).
37	const auditLogChangesMaxBytes = 16 * 1024
38	
39	// ─── GET /audit-log (list) ─────────────────────────────────────────────────
40	
41	// ParseAuditLogListQuery mirrors los filtros de
42	// `GET /audit-log?guild_id=&bot_id=&actor_id=&action=&status=&limit=&offset=`.
43	// `guild_id` es OBLIGATORIO (a diferencia de dbflowrun.ListParams, donde
44	// hasta guild_id es opcional); `bot_id`/`actor_id`/`action` son filtros de
45	// texto libre opcionales; `status` opcional se valida contra el enum
46	// cerrado; `limit` por defecto 25 (techo 100, vía el coerceLimit
47	// compartido), `offset` por defecto 0.
48	func ParseAuditLogListQuery(guildID, botID, actorID, action, status, limitRaw, offsetRaw string) (dbauditlog.ListFilter, int, int, *apierrors.CustomError) {
49		if guildID == "" {
50			return dbauditlog.ListFilter{}, 0, 0, zodItemError("guild_id is required", "guild_id")
51		}
52		filter := dbauditlog.ListFilter{GuildID: guildID}
53		if botID != "" {
54			v := botID
55			filter.BotID = &v
56		}
57		if actorID != "" {
58			v := actorID
59			filter.ActorID = &v
60		}
61		if action != "" {
62			v := action
63			filter.Action = &v
64		}
65		if status != "" {
66			if !auditLogStatusSet[status] {
67				return filter, 0, 0, zodItemError(auditLogStatusMsg, "status")
68			}
69			v := status
70			filter.Status = &v
71		}
72	
73		limitPtr, verr := coerceLimit(limitRaw, 100)
74		if verr != nil {
75			return filter, 0, 0, verr
76		}
77		offsetPtr, verr := coerceOffset(offsetRaw)
78		if verr != nil {
79			return filter, 0, 0, verr
80		}
81		limit := 25
82		if limitPtr != nil {
83			limit = *limitPtr
84		}
85		offset := 0
86		if offsetPtr != nil {
87			offset = *offsetPtr
88		}
89		return filter, limit, offset, nil
90	}
91	
92	// ─── POST /audit-log (create) ──────────────────────────────────────────────
93	
94	// ParseAuditLogCreate mirrors el body de creación de una fila:
95	// `{bot_id,guild_id,actor_id,actor_label?,action,target_type?,target_id?,
96	// status,changes?,route?}`. `bot_id`/`guild_id`/`actor_id`/`action`/`status`
97	// son REQUERIDOS; `action` además no puede ir vacía y tiene un techo de 128
98	// caracteres; el resto son opcionales y nullable. Orden de campos: bot_id,
99	// guild_id, actor_id, actor_label, action, target_type, target_id, status,
100	// changes, route — mirrors dbauditlog.Document.
101	func ParseAuditLogCreate(body []byte) (dbauditlog.CreateInput, *apierrors.CustomError) {
102		var raw struct {
103			BotID      json.RawMessage `json:"bot_id"`
104			GuildID    json.RawMessage `json:"guild_id"`
105			ActorID    json.RawMessage `json:"actor_id"`
106			ActorLabel json.RawMessage `json:"actor_label"`
107			Action     json.RawMessage `json:"action"`
108			TargetType json.RawMessage `json:"target_type"`
109			TargetID   json.RawMessage `json:"target_id"`
110			Status     json.RawMessage `json:"status"`
111			Changes    json.RawMessage `json:"changes"`
112			Route      json.RawMessage `json:"route"`
113		}
114		if err := json.Unmarshal(body, &raw); err != nil {
115			return dbauditlog.CreateInput{}, bodyBindError(err)
116		}
117	
118		var in dbauditlog.CreateInput
119		var verr *apierrors.CustomError
120		if in.BotID, verr = parseRequiredString(raw.BotID, "bot_id", 1, 0); verr != nil {
121			return in, verr
122		}
123		if in.GuildID, verr = parseRequiredString(raw.GuildID, "guild_id", 1, 0); verr != nil {
124			return in, verr
125		}
126		if in.ActorID, verr = parseRequiredString(raw.ActorID, "actor_id", 1, 0); verr != nil {
127			return in, verr
128		}
129		if in.ActorLabel, verr = parseNullableBoundedString(raw.ActorLabel, "actor_label", 0, 0); verr != nil {
130			return in, verr
131		}
132		if in.Action, verr = parseRequiredString(raw.Action, "action", 1, 128); verr != nil {
133			return in, verr
134		}
135		if in.TargetType, verr = parseNullableBoundedString(raw.TargetType, "target_type", 0, 0); verr != nil {
136			return in, verr
137		}
138		if in.TargetID, verr = parseNullableBoundedString(raw.TargetID, "target_id", 0, 0); verr != nil {
139			return in, verr
140		}
141		if in.Status, verr = parseEnumRequired(raw.Status, auditLogStatusSet, auditLogStatusMsg, "status"); verr != nil {
142			return in, verr
143		}
144		if in.Changes, verr = parseAuditLogChanges(raw.Changes); verr != nil {
145			return in, verr
146		}
147		if in.Route, verr = parseNullableBoundedString(raw.Route, "route", 0, 0); verr != nil {
148			return in, verr
149		}
150		return in, nil
151	}
152	
153	// parseAuditLogChanges mirrors parseNullableRecord (moderation_infractions_
154	// validations.go) pero decodifica directo a map[string]any (la forma que
155	// llevan CreateInput.Changes / Document.Changes — no hay una columna jsonb
156	// Postgres aguas abajo a la que pasarle los bytes crudos) y ADEMÁS impone el
157	// techo de auditLogChangesMaxBytes serializados. Ausente o JSON null → nil
158	// (renderiza como JSON null, igual que `AuditEntry.changes: Record<string,
159	// unknown> | null`).
160	func parseAuditLogChanges(raw json.RawMessage) (map[string]any, *apierrors.CustomError) {
161		if raw == nil || isJSONNull(raw) {
162			return nil, nil
163		}
164		if jsonKind(raw) != "object" {
165			return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), "changes")
166		}
167		if len(raw) > auditLogChangesMaxBytes {
168			return nil, zodItemError(fmt.Sprintf("Too big: expected changes to serialize to <=%d bytes", auditLogChangesMaxBytes), "changes")
169		}
170		var m map[string]any
171		if err := json.Unmarshal(raw, &m); err != nil {
172			return nil, zodItemError("Invalid input: expected record, received "+jsonKind(raw), "changes")
173		}
174		return m, nil
175	}
