	}
}

// DefaultModerationEscalation — apagado, ventana de 30 días, contando sólo los
// avisos (incluidos los de automod) y reiniciando el contador al disparar un
// peldaño. Sin peldaños: hay que definirlos desde la dashboard.
func DefaultModerationEscalation() ModerationEscalation {
	return ModerationEscalation{
