package validations

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"

	"kena.bot/api-db-go/internal/domain/dbleveling"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// Request DTOs + parsers para las seis rutas `/leveling/bots/:bot_id/guilds/:guild_id/**`
// (§8 del contrato original, §4 del contrato v4). Vertical NUEVA sin
// contraparte en el Node api-db, así que no hay un zod que mirrorear byte a
// byte — pero, a diferencia del resto del paquete
// (moderation_flow_runs_validations.go, etc.), esta vertical NUNCA responde
// 400 por `scope`, el descriptor de curva (`curve_mode`, `curve_multiplier`,
// `curve_thresholds`), `voice_metric`, un delta de XP, `limit` u `offset`
// ausentes o mal formados: el contrato v4 lo pide explícito para el
// descriptor completo ("ausentes o inválidos → formula, multiplicador 1,
// tabla vacía y métrica xp — nunca un error") y aquí se aplica el MISMO
// criterio a los demás, porque todos son parámetros de LECTURA/ESCRITURA
// DERIVADA (§3), no validaciones de negocio — el repositorio ya clampa
// limit/offset a sus rangos (ver LevelingRepository.Top). El único 400 real
// de esta vertical es `user_id` ausente dentro de una entrada de
// `POST /xp/bulk` (no tiene default razonable) o un body que ni siquiera es
// JSON válido.
//
// Cada pieza del descriptor se normaliza de forma INDEPENDIENTE, nunca en
// cascada (ver buildLevelingCurve): un `curve_thresholds` vacío o inválido
// NUNCA arrastra `curve_mode` de vuelta a "formula", ni viceversa — así una
// tabla manual a medio configurar (`curve_mode=manual&curve_thresholds=`,
// el caso de una tabla vacía) sigue siendo modo manual con cero umbrales,
// no degrada silenciosamente a la curva automática.
//
// Reusa los helpers compartidos del paquete: parseRequiredString,
// bodyBindError, isJSONNull (definidos en otros ficheros de este mismo
// paquete).

// levelingDefaultTopLimit es el default de `limit` en GET .../top cuando el
// query param falta o no es numérico — no lo fija el contrato, pero es el
// tamaño habitual de un leaderboard "top". El repositorio clampa el valor
// final (venga de aquí o del cliente) a [1,100].
const levelingDefaultTopLimit = 10

// parseLevelingInt intenta leer `raw` como entero; ausente o no numérico →
// `def`. Sin validación estricta a propósito (ver el comentario de
// package): limit/offset son parámetros de lectura derivada y el
// repositorio ya los clampa a su rango válido.
func parseLevelingInt(raw string, def int) int {
	if raw == "" {
		return def
	}
	v, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return def
	}
	return v
}

// parseLevelingCurveMultiplier interpreta el query param `curve_multiplier`:
// ausente, no numérico, no-positivo, NaN o infinito → 1 (el default de
// DBModuleLeveling — §4: "si falta o no es válido, default 1"). Nunca
// produce un 400.
func parseLevelingCurveMultiplier(raw string) float64 {
	if raw == "" {
		return 1
	}
	v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
	if err != nil || v <= 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		return 1
	}
	return v
}

// parseLevelingCurveMultiplierBody es el equivalente de
// parseLevelingCurveMultiplier para el campo `curve_multiplier` del body
// (POST /users/:user_id/xp y POST /xp/bulk) — mismo default, mismas
// condiciones de invalidez.
func parseLevelingCurveMultiplierBody(raw json.RawMessage) float64 {
	if raw == nil || isJSONNull(raw) {
		return 1
	}
	var v float64
	if err := json.Unmarshal(raw, &v); err != nil || v <= 0 || math.IsNaN(v) || math.IsInf(v, 0) {
		return 1
	}
	return v
}

// parseLevelingCurveThresholdsQuery interpreta el query param
// `curve_thresholds`: enteros >=1 separados por comas. Ausente o vacío
// ("" — Fiber no distingue "clave ausente" de "clave presente con valor
// vacío": las dos llegan como cadena vacía a c.Query, y las dos representan
// una tabla manual SIN configurar, §2) → cero umbrales, NUNCA "usa el
// default": una tabla manual vacía es un estado legítimo a medio
// configurar, no un motivo para caer a la curva automática. Cualquier token
// que no parsee como entero >=1 se DESCARTA individualmente en vez de
// invalidar la petición entera (§4: "ausentes o inválidos → ... tabla
// vacía", nunca un 400) — el resultado nunca es nil.
func parseLevelingCurveThresholdsQuery(raw string) []int64 {
	if raw == "" {
		return []int64{}
	}
	parts := strings.Split(raw, ",")
	out := make([]int64, 0, len(parts))
	for _, p := range parts {
		n, err := strconv.ParseInt(strings.TrimSpace(p), 10, 64)
		if err != nil || n < 1 {
			continue
		}
		out = append(out, n)
	}
	return out
}

// parseLevelingCurveThresholdsBody es el equivalente de
// parseLevelingCurveThresholdsQuery para el campo `curve_thresholds` del
// body (array de enteros, §4) — mismo criterio de descarte por elemento
// (un `[]` explícito o ausente/null da cero umbrales igual), nunca invalida
// la petición entera.
func parseLevelingCurveThresholdsBody(raw json.RawMessage) []int64 {
	if raw == nil || isJSONNull(raw) {
		return []int64{}
	}
	var nums []float64
	if err := json.Unmarshal(raw, &nums); err != nil {
		return []int64{}
	}
	out := make([]int64, 0, len(nums))
	for _, f := range nums {
		n := int64(f)
		if n < 1 {
			continue
		}
		out = append(out, n)
	}
	return out
}

// parseLevelingStringBody extrae un string plano de un campo del body —
// ausente, null o de otro tipo → "" (que NormalizeCurveMode/
// NormalizeVoiceMetric degradan a su default inofensivo en
// buildLevelingCurve).
func parseLevelingStringBody(raw json.RawMessage) string {
	if raw == nil || isJSONNull(raw) {
		return ""
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return ""
	}
	return s
}

// parseLevelingNonNegInt64 interpreta un delta de XP del body (text_xp,
// voice_xp, messages, voice_seconds): ausente o null → 0; negativo o de
// otro tipo → 0 (clampeado, nunca 400 — ver el comentario de package); si
// no, el entero (truncado si llega con decimales).
func parseLevelingNonNegInt64(raw json.RawMessage) int64 {
	if raw == nil || isJSONNull(raw) {
		return 0
	}
	var v float64
	if err := json.Unmarshal(raw, &v); err != nil || v < 0 {
		return 0
	}
	return int64(v)
}

// parseLevelingBool interpreta `touch_message`: ausente, null o cualquier
// valor no-booleano → false.
func parseLevelingBool(raw json.RawMessage) bool {
	if raw == nil || isJSONNull(raw) {
		return false
	}
	var b bool
	if err := json.Unmarshal(raw, &b); err != nil {
		return false
	}
	return b
}

// buildLevelingCurve ensambla el descriptor final (dbleveling.Curve) más el
// `voiceMetric` normalizado a partir de piezas YA extraídas como tipos Go
// planos (venga de query string o de body JSON ya decodificado). Cada pieza
// se normaliza de forma INDEPENDIENTE — ver el comentario de package sobre
// por qué nunca en cascada.
func buildLevelingCurve(modeRaw string, multiplier float64, thresholds []int64, voiceMetricRaw string) (dbleveling.Curve, string) {
	curve := dbleveling.Curve{
		Mode:       dbleveling.NormalizeCurveMode(modeRaw),
		Multiplier: multiplier,
		Thresholds: thresholds,
	}
	return curve, dbleveling.NormalizeVoiceMetric(voiceMetricRaw)
}

// ─── GET /leveling/bots/:bot_id/guilds/:guild_id/top ──────────────────────

// ParseLevelingTopQuery mirrors la query de GET .../top: `scope` (default
// "unified" — dbleveling.NormalizeScope), el descriptor de curva completo
// (`curve_mode`, `curve_multiplier`, `curve_thresholds`), `voice_metric`
// (default "xp"), `limit` (default levelingDefaultTopLimit, el repositorio
// clampa a [1,100]), `offset` (default 0, el repositorio clampa a >=0).
func ParseLevelingTopQuery(scope, curveModeRaw, curveMultiplierRaw, curveThresholdsRaw, voiceMetricRaw, limitRaw, offsetRaw string) (normScope string, curve dbleveling.Curve, voiceMetric string, limit, offset int) {
	curve, voiceMetric = buildLevelingCurve(
		curveModeRaw,
		parseLevelingCurveMultiplier(curveMultiplierRaw),
		parseLevelingCurveThresholdsQuery(curveThresholdsRaw),
		voiceMetricRaw,
	)
	return dbleveling.NormalizeScope(scope),
		curve,
		voiceMetric,
		parseLevelingInt(limitRaw, levelingDefaultTopLimit),
		parseLevelingInt(offsetRaw, 0)
}

// ─── GET /leveling/bots/:bot_id/guilds/:guild_id/users/:user_id ───────────

// ParseLevelingUserQuery mirrors la query de GET .../users/:user_id:
// `scope` (default "unified") + el mismo descriptor de curva y
// `voice_metric` que ParseLevelingTopQuery.
func ParseLevelingUserQuery(scope, curveModeRaw, curveMultiplierRaw, curveThresholdsRaw, voiceMetricRaw string) (normScope string, curve dbleveling.Curve, voiceMetric string) {
	curve, voiceMetric = buildLevelingCurve(
		curveModeRaw,
		parseLevelingCurveMultiplier(curveMultiplierRaw),
		parseLevelingCurveThresholdsQuery(curveThresholdsRaw),
		voiceMetricRaw,
	)
	return dbleveling.NormalizeScope(scope), curve, voiceMetric
}

// ─── POST /leveling/bots/:bot_id/guilds/:guild_id/users/:user_id/xp ───────

// ParseLevelingAddXP mirrors el body de POST .../users/:user_id/xp:
// `{text_xp?, voice_xp?, messages?, voice_seconds?, curve_mode?,
// curve_multiplier?, curve_thresholds?, voice_metric?, touch_message?}` —
// TODOS opcionales. Un body vacío (`{}`, `null`, o ausente) es válido: los
// cuatro deltas quedan a 0, que es el "touch" del §3 (re-deriva y persiste
// los niveles de este miembro sin conceder XP). El único error posible es
// un body que ni siquiera es JSON válido.
func ParseLevelingAddXP(body []byte) (dbleveling.AddXPInput, *apierrors.CustomError) {
	var raw struct {
		TextXP          json.RawMessage `json:"text_xp"`
		VoiceXP         json.RawMessage `json:"voice_xp"`
		Messages        json.RawMessage `json:"messages"`
		VoiceSeconds    json.RawMessage `json:"voice_seconds"`
		CurveMode       json.RawMessage `json:"curve_mode"`
		CurveMultiplier json.RawMessage `json:"curve_multiplier"`
		CurveThresholds json.RawMessage `json:"curve_thresholds"`
		VoiceMetric     json.RawMessage `json:"voice_metric"`
		TouchMessage    json.RawMessage `json:"touch_message"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &raw); err != nil {
			return dbleveling.AddXPInput{}, bodyBindError(err)
		}
	}
	curve, voiceMetric := buildLevelingCurve(
		parseLevelingStringBody(raw.CurveMode),
		parseLevelingCurveMultiplierBody(raw.CurveMultiplier),
		parseLevelingCurveThresholdsBody(raw.CurveThresholds),
		parseLevelingStringBody(raw.VoiceMetric),
	)
	return dbleveling.AddXPInput{
		TextXP:       parseLevelingNonNegInt64(raw.TextXP),
		VoiceXP:      parseLevelingNonNegInt64(raw.VoiceXP),
		Messages:     parseLevelingNonNegInt64(raw.Messages),
		VoiceSeconds: parseLevelingNonNegInt64(raw.VoiceSeconds),
		Curve:        curve,
		VoiceMetric:  voiceMetric,
		TouchMessage: parseLevelingBool(raw.TouchMessage),
	}, nil
}

// ─── POST /leveling/bots/:bot_id/guilds/:guild_id/xp/bulk ─────────────────

// ParseLevelingAddXPBulk mirrors el body de POST .../xp/bulk:
// `{entries: [{user_id, text_xp?, voice_xp?, messages?, voice_seconds?,
// touch_message?}], curve_mode?, curve_multiplier?, curve_thresholds?,
// voice_metric?}`. `user_id` es el ÚNICO campo REQUERIDO de todo este
// endpoint — dentro de cada entrada, no tiene un default razonable — y
// falla con el índice exacto en la property (`entries.N.user_id`) para
// señalar la fila. `entries` ausente o vacío es válido: el repositorio lo
// trata como no-op. El descriptor de curva y `voice_metric` son
// COMPARTIDOS por todo el lote (§4), no por entrada.
func ParseLevelingAddXPBulk(body []byte) ([]dbleveling.BulkEntry, dbleveling.Curve, string, *apierrors.CustomError) {
	var raw struct {
		Entries []struct {
			UserID       json.RawMessage `json:"user_id"`
			TextXP       json.RawMessage `json:"text_xp"`
			VoiceXP      json.RawMessage `json:"voice_xp"`
			Messages     json.RawMessage `json:"messages"`
			VoiceSeconds json.RawMessage `json:"voice_seconds"`
			TouchMessage json.RawMessage `json:"touch_message"`
		} `json:"entries"`
		CurveMode       json.RawMessage `json:"curve_mode"`
		CurveMultiplier json.RawMessage `json:"curve_multiplier"`
		CurveThresholds json.RawMessage `json:"curve_thresholds"`
		VoiceMetric     json.RawMessage `json:"voice_metric"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &raw); err != nil {
			return nil, dbleveling.Curve{}, "", bodyBindError(err)
		}
	}

	entries := make([]dbleveling.BulkEntry, 0, len(raw.Entries))
	for i, e := range raw.Entries {
		userID, verr := parseRequiredString(e.UserID, fmt.Sprintf("entries.%d.user_id", i), 1, 32)
		if verr != nil {
			return nil, dbleveling.Curve{}, "", verr
		}
		entries = append(entries, dbleveling.BulkEntry{
			UserID:       userID,
			TextXP:       parseLevelingNonNegInt64(e.TextXP),
			VoiceXP:      parseLevelingNonNegInt64(e.VoiceXP),
			Messages:     parseLevelingNonNegInt64(e.Messages),
			VoiceSeconds: parseLevelingNonNegInt64(e.VoiceSeconds),
			TouchMessage: parseLevelingBool(e.TouchMessage),
		})
	}
	curve, voiceMetric := buildLevelingCurve(
		parseLevelingStringBody(raw.CurveMode),
		parseLevelingCurveMultiplierBody(raw.CurveMultiplier),
		parseLevelingCurveThresholdsBody(raw.CurveThresholds),
		parseLevelingStringBody(raw.VoiceMetric),
	)
	return entries, curve, voiceMetric, nil
}

