// asModerationRawMap acepta las tres formas en las que puede llegar un
// sub-documento anidado. La tercera es la importante: el driver de Mongo v2
// decodifica TODO documento anidado dentro de un `bson.M` como `bson.D` (el
// mecanismo de "ancestor" del v1, que propagaba `bson.M` hacia abajo,
// desapareció). Con el `asBsonMap` genérico —que sólo mira `bson.M` y
// `map[string]any`— la migración creería que el bloque no existe y lo pisaría
// con los defaults en CADA lectura, borrando la configuración del servidor.
func asModerationRawMap(v any) (bson.M, bool) {
	switch m := v.(type) {
	case bson.M:
		return m, true
	case map[string]any:
		return bson.M(m), true
	case bson.D:
		out := make(bson.M, len(m))
		for _, e := range m {
			out[e.Key] = e.Value
		}
		return out, true
	}
	return nil, false
}

	// Stamp the source from the repo even on the not-found path — the FindModule
	// no-document branch still carries "db" / the module detail, mirroring the
	// Node applySourceAndStash(sourced{data:null}).
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	// La revisión viaja en `ETag`, NO en el cuerpo (`Rev` es `json:"-"`): el JSON
	// no cambia para ningún cliente. Quien quiera protegerse del lost update sólo
	// tiene que devolver esta revisión en `If-Match` al guardar.
	c.Set(fiber.HeaderETag, etagRev(d.Rev))
	r.SetData(&d)
	return reply(c, r)
}

// Patch mirrors `patchModuleModmailController`. Strict body (DisallowUnknownFields,
// matching the zod `.strict()`) validates the shape; the SAME body is then
// re-decoded as a raw `map[string]any` so key PRESENCE survives, and the repo
// MergeDeepJSON-merges it into the current subdoc — a partial nested PATCH
// preserves sibling keys and explicit `false`/`0`/`null` leaves are APPLIED
// (mirrors the Node `mergeDeep`). An empty body `{}` is a no-op that still
// bumps schema_version (Node returns 200). A missing guild → 400
// MODULE_NOT_FOUND with `data:null`.
func (h *ModuleModmailHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModmail]()
	ctx := c.Context()

	var body validations.UpdateModuleModmailBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// Ids de los tipos de ticket: reservados y duplicados se rechazan AQUÍ, en el
	// servidor. El dashboard ya lo valida con zod, pero eso no protege de un
	// cliente con token que hable directo con la API — y un tipo real que robe el
	// centinela se lleva por delante todo el histórico sin clasificar.
	if body.TicketTypes != nil {
		if verr := validations.ValidateModmailTicketTypes(*body.TicketTypes); verr != nil {
			r.AddError(verr)
			return reply(c, r)
		}
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// `If-Match` es OPCIONAL: quien no la manda escribe como siempre. Quien la
	// manda pide que el servidor rechace su escritura si el documento cambió desde
	// que él lo leyó, en vez de pisar en silencio lo que guardó otro.
	ifRev := parseIfMatchRev(c.Get(fiber.HeaderIfMatch))

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch, ifRev)
	if err != nil {
		// Escritura rancia: conflicto DEL CLIENTE (su copia es vieja), no un fallo
		// del servidor — 409, y en Mongo no se ha tocado nada. Tiene que ir antes
		// del 500 genérico de abajo.
		if stderrors.Is(err, mongorepo.ErrStaleModmailWrite) {
			r.AddError(apierrors.Conflict(err.Error(), apierrors.CodeStaleWrite))
			return reply(c, r)

package mongo

import (
	"context"
	stderrors "errors"
	"fmt"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"

	"kena.bot/api-db-go/internal/domain/dbguild"
	"kena.bot/api-db-go/internal/domain/mocks"
	"kena.bot/api-db-go/internal/infrastructure/locker"
	"kena.bot/api-db-go/internal/infrastructure/redis"
)

// ModuleModerationRepository owns reads / writes against the `module_moderation`
// subdoc of the `guilds` collection plus its dedicated Redis cache.
//
// Cache layout (matches Node's `DBModuleCache`):
//
//	bots:{botId}:guilds:{guildId}:modules:moderation    HASH (TTL: OneHour)
//
// Source-detail strings mirror the Node values. The Node moderation GET goes
// through the shared `ModuleRepository.findModule` (which stamps
// "mongo.guild.module") while the PATCH success path stamps
// "mongo.guild.module_moderation"; the Go port consolidates on the per-module
// detail for BOTH paths, matching the greeter/logs/modmail/tempvoice/giveaway
// verticals (a pre-existing, accepted divergence on the GET-path detail only).
// The cache detail is identical to Node.
const (
	SourceDetailModuleModerationCache = "redis:cache.db.module"
	SourceDetailModuleModerationDB    = "mongo.guild.module_moderation"
)

// ModuleModerationRepository is the moderation-specific facade. Mirrors the Node
// `ModuleModerationRepository` — greeter-shaped cache+locker structure, and (like
// greeter/logs/modmail/tempvoice/giveaway) the update path MergeDeep-merges the
// patch into the current subdoc, matching the Node repo's recursive `mergeDeep`.
type ModuleModerationRepository struct {
	coll  *mongo.Collection
	cache *redis.ModuleCache
	lk    *locker.Locker
}

func (r *ModuleModerationRepository) WithLocker(lk *locker.Locker) *ModuleModerationRepository {
	r.lk = lk
	return r
}

func (r *ModuleModerationRepository) lockKey(key string) func() {
	if r.lk != nil {
		return r.lk.Lock(key)
	}
	return locker.LocalOnly(key)
}

// NewModuleModerationRepository wires the cache + collection.
func NewModuleModerationRepository(db *mongo.Database, cache *redis.ModuleCache) *ModuleModerationRepository {
	return &ModuleModerationRepository{
		coll:  db.Collection("guilds"),
		cache: cache,
	}
}

// FindModule returns the moderation subdoc, cache-first. On cache miss it falls
// back to Mongo with a `module_moderation` projection, fills any defaulted
// fields via `mocks.NewModuleModeration()`, normalises the nested collections,
// and writes the result to cache with TTL=OneHour. `force` evicts the cache
// before the read so the slow path rebuilds from Mongo — mirrors the Node
// moderation controller's `?force` query forwarded to `findModule({ force })`
// (same as tempvoice/greeter/giveaway).
func (r *ModuleModerationRepository) FindModule(ctx context.Context, botID, guildID string, force bool) (*Sourced[dbguild.ModuleModeration], error) {
	// `force` evicts the cache before the read so the slow path rebuilds from
	// Mongo. Mirrors the Node `findModule({ force: true })`.
	if force {
		_ = r.cache.DeleteModule(ctx, botID, guildID, "moderation")
	}

	// Cache fast-path.
	if !force {
		if cached, err := r.cache.GetModule(ctx, botID, guildID, "moderation"); err == nil && cached != nil {
			var m dbguild.ModuleModeration
			if err := mapToModuleModeration(cached, &m); err == nil && m.SchemaVersion != 0 {
				dbguild.NormalizeModeration(&m)
				return &Sourced[dbguild.ModuleModeration]{
					Data:         m,
					Source:       "cache",
					SourceDetail: SourceDetailModuleModerationCache,
				}, nil
			}
			// Parse failure or stale schema → drop and re-read.
			_ = r.cache.DeleteModule(ctx, botID, guildID, "moderation")
		}
	}

	// Slow path: project just the module_moderation block.
	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	projection := bson.M{"module_moderation": 1}
	var out struct {
		ModuleModeration bson.M `bson:"module_moderation"`
	}
	if err := r.coll.FindOne(ctx, filter, options.FindOne().SetProjection(projection)).Decode(&out); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return &Sourced[dbguild.ModuleModeration]{
				Data:         dbguild.ModuleModeration{},
				Source:       "db",
				SourceDetail: SourceDetailModuleModerationDB,
			}, nil
		}
		return nil, err
	}

	// Se decodifica a bson.M + MigrateModerationRaw (espejo de tempvoice/música).
	// Un decode directo al struct dejaría a CERO todos los bloques del v3 que un
	// documento v2 no tiene (`protection`, `raid`, `antinuke`…), y sus defaults
	// no son valores cero: ventanas, umbrales y `timeout_ms`. La migración se
	// ejecuta SIN fiarse del `schema_version` almacenado — una escritura pudo
	// sellar la versión actual sobre una forma sin migrar (el "veneno" que rompió
	// tempvoice).
	raw := out.ModuleModeration
	var m dbguild.ModuleModeration
	if len(raw) == 0 || dbguild.ModerationRawSchemaVersion(raw) == 0 {
		m = mocks.NewModuleModeration()
	} else {
		m = dbguild.MigrateModerationRaw(raw)
	}
	dbguild.NormalizeModeration(&m)

	if fields, err := redis.MarshalModuleModeration(m); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "moderation", fields, redis.ModuleTTLSeconds)
	}

	return &Sourced[dbguild.ModuleModeration]{
		Data:         m,
		Source:       "db",
		SourceDetail: SourceDetailModuleModerationDB,
	}, nil
}

// Update applies the partial body to the moderation subdoc. The merge is
// `MergeDeepJSON` (recursive, presence-based) — the SAME read-merge-write path
// greeter/logs/modmail/tempvoice/giveaway use, mirroring the Node
// `ModuleModerationRepository.update` `mergeDeep`. A body carrying a single
// scalar only touches that one leaf (every other field survives); the nested
// blocks (`commands_global`, `mute`, `automod`) merge per-field, and the
// `commands` map merges per-KEY and RECURSES into each provided command value
// (both sides are JSON objects) — exact Node parity. Explicit
// `false`/`0`/`null` leaves are APPLIED: an `enabled:false` PATCH persists,
// and a nullable field (`log_channel_id`, `mute.role_id`) sent as explicit
// JSON `null` is CLEARED — Node's `mergeDeep` only skips `undefined`.
//
// Like greeter/tempvoice/giveaway, moderation carries a per-module
// `updated_at`; the repo stamps it to `now` AFTER the merge — the strict PATCH
// body rejects `updated_at`, and Node's `mergeDeep({...data, updated_at: new
// Date()})` always overwrites it. The guild-level `updatedAt` is also bumped
// via `$currentDate` (matching the Node `guild.save()` timestamps). The Node
// `checkGuildExists`→GUILD_NOT_FOUND pre-check is omitted per the greeter
// mold — see the handler.
//
// The full read-merge-write-cache cycle is serialised per guild.
func (r *ModuleModerationRepository) Update(ctx context.Context, botID, guildID string, patch map[string]any) (*Sourced[dbguild.ModuleModeration], error) {
	unlock := r.lockKey("moderation:" + botID + "\x00" + guildID)
	defer unlock()

	filter := bson.M{"bot_id": botID, "guild_id": guildID}
	var before struct {
		ModuleModeration bson.M `bson:"module_moderation"`
	}
	if err := r.coll.FindOne(ctx, filter).Decode(&before); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module moderation update (pre-read): %w", err)
	}

	// Se migra el documento existente ANTES del merge y del sellado de versión
	// (espejo de tempvoice/música): así los bloques del v3 que falten llegan al
	// merge con sus defaults y nunca se persiste una forma sin migrar bajo la
	// versión actual. El merge trabaja sobre una copia, de modo que la vista del
	// llamante nunca queda a medias.
	raw := before.ModuleModeration
	var merged dbguild.ModuleModeration
	if len(raw) == 0 || dbguild.ModerationRawSchemaVersion(raw) == 0 {
		merged = mocks.NewModuleModeration()
	} else {
		merged = dbguild.MigrateModerationRaw(raw)
	}
	// El `enabled_since` ALMACENADO se captura AQUÍ, antes del merge: `before`
	// es un `bson.M` crudo, así que el valor tipado sólo existe una vez que la
	// migración lo ha decodificado, y el merge posterior puede pisarlo.
	storedEnabledSince := merged.EnabledSince
	if err := MergeDeepJSON(&merged, patch); err != nil {
		return nil, fmt.Errorf("module moderation update (merge): %w", err)
	}
	// Stamp server-side `updated_at` to `now` AFTER the merge (see doc above).
	merged.UpdatedAt = dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))
	// Stamp schema_version directly on the merged struct so we don't conflict
	// with the parent `module_moderation` set in the same `$set`.
	merged.SchemaVersion = dbguild.SchemaVersionModeration
	// Guarantee the nested collections stay non-nil ([] / {}) after the merge.
	dbguild.NormalizeModeration(&merged)

	// `enabled_since` es WRITE-ONCE y EXCLUSIVAMENTE server-side. Se restaura
	// primero el valor ALMACENADO, pisando lo que el merge haya podido dejar:
	// sin esta línea un cliente que enviara `enabled_since` en el PATCH se
	// auto-concedería derecho legacy permanente.
	merged.EnabledSince = storedEnabledSince

	// Se estampa la PRIMERA vez que el módulo queda activado y no se reescribe
	// nunca: desactivar no lo borra y reactivar no lo pisa — el derecho legacy
	// se conserva para siempre (decisión de producto).
	if merged.Enabled && merged.EnabledSince == nil {
		stamp := dbguild.NewDate(time.Now().UTC().Truncate(time.Millisecond))
		merged.EnabledSince = &stamp
	}

	update := bson.M{
		"$set": bson.M{
			"module_moderation": merged,
		},
		"$currentDate": bson.M{"updatedAt": true},
	}
	opt := options.FindOneAndUpdate().SetReturnDocument(options.After)
	opt = opt.SetProjection(bson.M{"module_moderation": 1})
	var after struct {
		ModuleModeration dbguild.ModuleModeration `bson:"module_moderation"`
	}
	if err := r.coll.FindOneAndUpdate(ctx, filter, update, opt).Decode(&after); err != nil {
		if stderrors.Is(err, mongo.ErrNoDocuments) {
			return nil, nil
		}
		return nil, fmt.Errorf("module moderation update: %w", err)
	}

	m := after.ModuleModeration
	dbguild.NormalizeModeration(&m)

	if fields, err := redis.MarshalModuleModeration(m); err == nil {
		_ = r.cache.SetModule(ctx, botID, guildID, "moderation", fields, redis.ModuleTTLSeconds)
	}

	// The write may have flipped `enabled`, so the guild's enabled_modules
	// snapshot can no longer be trusted. See invalidateEnabledSnapshot.
	invalidateEnabledSnapshot(ctx, r.cache, botID, guildID, "moderation")

	return &Sourced[dbguild.ModuleModeration]{
		Data:         m,
		Source:       "db",
		SourceDetail: SourceDetailModuleModerationDB,
	}, nil
}

// mapToModuleModeration unmarshals a raw cache hash into the typed module.
// Best-effort: a parse failure returns the error so the caller can invalidate
// the cache and re-read from Mongo. Same bson round-trip greeter/tempvoice use —
// GetModule has already deserialised the JSON-encoded nested blocks
// (`commands_global`, `commands`, `mute`, `automod`) into map values and the
// `__DATE__:` `updated_at` into a native time.Time, and the `log_channel_id`
// empty ("") cache value back into a nil that bson round-trips to a nil
// `*string`.
func mapToModuleModeration(raw map[string]any, out *dbguild.ModuleModeration) error {
	b, err := bson.Marshal(raw)
	if err != nil {
		return err
	}
	return bson.Unmarshal(b, out)
}

