package dbguild

import (
	"go.mongodb.org/mongo-driver/v2/bson"
)

// This file mirrors the `DBModuleModeration` family in
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. The field
// ORDER of every struct matches the corresponding zod object schema in
// `apis/api-db/src/domain/zod-schemas/mongo/guild-schema.ts` (which happens to
// match the TS interface order): the Node GET response is produced by
// `moduleModerationSchema.parse(...)`, which normalises key order to the
// schema-definition order — so matching that order keeps the JSON body
// byte-for-byte identical.
//
// The moderation module is per-guild moderation CONFIG only (command mode +
// per-command access/DM, the hybrid-mute strategy, the mod-log channel, the
// AutoMod ruleset and — from v3 — the protection / escalation / effects / raid
// / gate / antinuke / lockdown blocks). The concrete sanctions (infractions)
// live in Postgres (`moderation.infractions`), NOT here.
//
// Nullable fields (`string | null` in TS) use pointer types so JSON encoding
// emits `null` (not `""`) for the unset variant: `log_channel_id`,
// `mute.role_id`, each command's `dm_embed.color`, and the v3
// `raid.alert_*`/`gate.alert_channel_id`/`antinuke.alert_*`. Collection fields
// (`[]string`, `Record<...>`) are never `omitempty`: a present-but-empty value
// must serialise as `[]` / `{}`, never `null`. `NormalizeModeration` backfills
// nil collections so the invariant holds for docs decoded from Mongo/Redis.
//
// Los defaults viven en ESTE paquete (y no en `mocks`) por dos razones: el
// paquete `mocks` ya importa `dbguild`, así que la migración no podría llamarlo
// sin ciclo; y así el seed del documento nuevo y el backfill del documento
// viejo comparten UNA sola fuente de verdad. Mismo patrón que
// `DefaultMusicCommands`.

// ModerationCommandMode mirrors `ModerationCommandMode` (`"slash" | "prefix" |
// "both"`) — how the moderation commands may be invoked (same pattern as
// tempvoice).
type ModerationCommandMode string

const (
	ModerationCommandModeSlash  ModerationCommandMode = "slash"
	ModerationCommandModePrefix ModerationCommandMode = "prefix"
	ModerationCommandModeBoth   ModerationCommandMode = "both"
)

// ModerationMuteMode mirrors `ModerationMuteMode` (`"auto" | "timeout" |
// "role"`) — the hybrid-mute application strategy (native timeout ≤28d / silence
// role).
type ModerationMuteMode string

const (
	ModerationMuteModeAuto    ModerationMuteMode = "auto"
	ModerationMuteModeTimeout ModerationMuteMode = "timeout"
	ModerationMuteModeRole    ModerationMuteMode = "role"
)

// ModerationAccessMode mirrors `DBAccessMode` (`"only" | "all_except"`) — the
// mode of a command access list. `only` = allowlist, `all_except` = denylist.
// Defined locally (not shared with tempvoice) to keep the verticals decoupled,
// matching how tempvoice/modmail each define their own.
type ModerationAccessMode string

const (
	ModerationAccessOnly      ModerationAccessMode = "only"
	ModerationAccessAllExcept ModerationAccessMode = "all_except"
)

// AutomodAction mirrors `AutomodAction` (`"delete" | "delete_warn" |
// "delete_timeout" | "delete_kick" | "delete_ban"`) — what the AutoMod does when
// a rule fires: delete only, delete + DM warning, delete + tempmute
// (`timeout_ms`), delete + kick, or delete + ban. Los tres primeros son los del
// v2 y siguen siendo válidos: la ampliación del v3 es ADITIVA y ningún
// documento existente necesita migrarse por ella.
type AutomodAction string

const (
	AutomodActionDelete        AutomodAction = "delete"
	AutomodActionDeleteWarn    AutomodAction = "delete_warn"
	AutomodActionDeleteTimeout AutomodAction = "delete_timeout"
	AutomodActionDeleteKick    AutomodAction = "delete_kick"
	AutomodActionDeleteBan     AutomodAction = "delete_ban"
)

// ModerationEscalationAction mirrors `ModerationEscalationAction` — la sanción
// que aplica un peldaño del escalado automático.
type ModerationEscalationAction string

const (
	ModerationEscalationMute     ModerationEscalationAction = "mute"
	ModerationEscalationTempmute ModerationEscalationAction = "tempmute"
	ModerationEscalationKick     ModerationEscalationAction = "kick"
	ModerationEscalationTempban  ModerationEscalationAction = "tempban"
	ModerationEscalationBan      ModerationEscalationAction = "ban"
)

// InfractionCountableType mirrors `InfractionCountableType` — los tipos de
// infracción que pueden sumar al contador del escalado automático.
type InfractionCountableType string

const (
	InfractionCountableWarn     InfractionCountableType = "warn"
	InfractionCountableNote     InfractionCountableType = "note"
	InfractionCountableMute     InfractionCountableType = "mute"
	InfractionCountableTempmute InfractionCountableType = "tempmute"
	InfractionCountableKick     InfractionCountableType = "kick"
	InfractionCountableBan      InfractionCountableType = "ban"
	InfractionCountableTempban  InfractionCountableType = "tempban"
)

// ModerationEffectPolicy mirrors `ModerationEffectPolicy` — cuándo se aplica un
// efecto secundario de sanción: siempre, nunca, o lo decide el moderador en el
// momento (`ask`, que cae en `default` si no pasa la opción).
type ModerationEffectPolicy string

const (
	ModerationEffectAlways ModerationEffectPolicy = "always"
	ModerationEffectNever  ModerationEffectPolicy = "never"
	ModerationEffectAsk    ModerationEffectPolicy = "ask"
)

// ModerationRaidAction mirrors `ModerationRaidAction` — qué hace el módulo
// cuando detecta una oleada de entradas.
type ModerationRaidAction string

const (
	ModerationRaidAlert    ModerationRaidAction = "alert"
	ModerationRaidLockdown ModerationRaidAction = "lockdown"
	ModerationRaidKick     ModerationRaidAction = "kick"
	ModerationRaidBan      ModerationRaidAction = "ban"
)

// ModerationGateAction mirrors `ModerationGateAction` — qué se hace con un
// miembro que no pasa el filtro de entrada.
type ModerationGateAction string

const (
	ModerationGateAlert ModerationGateAction = "alert"
	ModerationGateKick  ModerationGateAction = "kick"
	ModerationGateBan   ModerationGateAction = "ban"
	ModerationGateMute  ModerationGateAction = "mute"
)

// ModerationNukeAction mirrors `ModerationNukeAction` — las acciones
// destructivas que vigila el anti-nuke. Se leen del registro de auditoría
// (`GUILD_AUDIT_LOG_ENTRY_CREATE`), que es lo único que dice QUIÉN hizo cada
// cosa.
type ModerationNukeAction string

const (
	ModerationNukeChannelDelete    ModerationNukeAction = "channel_delete"
	ModerationNukeChannelCreate    ModerationNukeAction = "channel_create"
	ModerationNukeChannelUpdate    ModerationNukeAction = "channel_update"
	ModerationNukeRoleDelete       ModerationNukeAction = "role_delete"
	ModerationNukeRoleCreate       ModerationNukeAction = "role_create"
	ModerationNukeRoleUpdate       ModerationNukeAction = "role_update"
	ModerationNukeMemberBan        ModerationNukeAction = "member_ban"
	ModerationNukeMemberKick       ModerationNukeAction = "member_kick"
	ModerationNukeMemberPrune      ModerationNukeAction = "member_prune"
	ModerationNukeMemberRoleUpdate ModerationNukeAction = "member_role_update"
	ModerationNukeWebhookCreate    ModerationNukeAction = "webhook_create"
	ModerationNukeEmojiDelete      ModerationNukeAction = "emoji_delete"
	ModerationNukeGuildUpdate      ModerationNukeAction = "guild_update"
)

// ModerationNukeActionNames es el catálogo completo de acciones vigiladas, en
// el MISMO orden que la unión de TS. Lo usan el seed de `antinuke.limits` y su
// backfill en la migración.
var ModerationNukeActionNames = []ModerationNukeAction{
	ModerationNukeChannelDelete,
	ModerationNukeChannelCreate,
	ModerationNukeChannelUpdate,
	ModerationNukeRoleDelete,
	ModerationNukeRoleCreate,
	ModerationNukeRoleUpdate,
	ModerationNukeMemberBan,
	ModerationNukeMemberKick,
	ModerationNukeMemberPrune,
	ModerationNukeMemberRoleUpdate,
	ModerationNukeWebhookCreate,
	ModerationNukeEmojiDelete,
	ModerationNukeGuildUpdate,
}

// ModerationNukePunishment mirrors `ModerationNukePunishment` — el castigo que
// recibe el causante al reventar un límite del anti-nuke.
type ModerationNukePunishment string

const (
	ModerationNukePunishAlert      ModerationNukePunishment = "alert"
	ModerationNukePunishStripRoles ModerationNukePunishment = "strip_roles"
	ModerationNukePunishKick       ModerationNukePunishment = "kick"
	ModerationNukePunishBan        ModerationNukePunishment = "ban"
)

// ModerationNukePunishmentOrInherit mirrors `ModerationNukePunishmentOrInherit`
// — igual que `ModerationNukePunishment` más `inherit` (= usar el castigo
// global del bloque). Go no tiene uniones de tipos: los cuatro valores
// concretos se escriben convirtiendo
// (`ModerationNukePunishmentOrInherit(ModerationNukePunishBan)`), y sólo
// `inherit` tiene constante propia porque es el único valor que NO existe en el
// tipo base.
type ModerationNukePunishmentOrInherit string

const ModerationNukePunishInherit ModerationNukePunishmentOrInherit = "inherit"

// ModerationAccessList mirrors `DBAccessList` — the roles/channels/categories
// access list of a moderation command. Field order follows `accessListSchema`.
type ModerationAccessList struct {
	Mode ModerationAccessMode `bson:"mode" json:"mode"`
	IDs  []string             `bson:"ids"  json:"ids"`
}

// ModerationCommandAccess mirrors `DBCommandAccess` — the per-axis access of a
// command (who: roles, where: channels/categories). Field order follows
// `commandAccessSchema`.
type ModerationCommandAccess struct {
	Roles      ModerationAccessList `bson:"roles"      json:"roles"`
	Channels   ModerationAccessList `bson:"channels"   json:"channels"`
	Categories ModerationAccessList `bson:"categories" json:"categories"`
}

// ModerationDmEmbed mirrors `DBModerationDmEmbed` — the DM the sanctioned user
// receives (rich-text content + accent color). `Color` is nullable (`null` =
// the module's accent color). Field order follows the zod `dm_embed` object.
type ModerationDmEmbed struct {
	Content string  `bson:"content" json:"content"`
	Color   *string `bson:"color"   json:"color"`
}

// ModerationCommand mirrors `DBModerationCommand` — per-command config: the
// shared access model (enabled/use_global/access) plus the per-command DM
// notice (aliases + dm_enabled + dm_embed). Unlike tempvoice v8, `use_global`
// is a plain BOOLEAN here (inherit the whole global block, not per-axis). Field
// order follows `moderationCommandSchema`.
type ModerationCommand struct {
	Enabled   bool                    `bson:"enabled"    json:"enabled"`
	UseGlobal bool                    `bson:"use_global" json:"use_global"`
	Access    ModerationCommandAccess `bson:"access"     json:"access"`
	Aliases   []string                `bson:"aliases"    json:"aliases"`
	DmEnabled bool                    `bson:"dm_enabled" json:"dm_enabled"`
	DmEmbed   ModerationDmEmbed       `bson:"dm_embed"   json:"dm_embed"`
}

// ModerationMute mirrors `DBModuleModerationMute` — the hybrid-mute config
// (silence role + strategy). `RoleID` is nullable (`null` = not configured).
// Field order follows the zod `mute` object.
type ModerationMute struct {
	RoleID *string            `bson:"role_id" json:"role_id"`
	Mode   ModerationMuteMode `bson:"mode"    json:"mode"`
}

// AutomodMentionsRule mirrors `DBAutomodMentionsRule` — block mentions of
// certain users/roles, `@everyone`/`@here`, and/or mention spam. Field order
// follows `automodMentionsSchema` (the shared base fields first — con
// `count_as_warn` cerrando la base desde el v3 —, then the mentions-specific
// ones).
type AutomodMentionsRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	BlockedUsers   []string      `bson:"blocked_users"   json:"blocked_users"`
	BlockedRoles   []string      `bson:"blocked_roles"   json:"blocked_roles"`
	BlockEveryone  bool          `bson:"block_everyone"  json:"block_everyone"`
	MaxMentions    int           `bson:"max_mentions"    json:"max_mentions"`
}

// AutomodWordsRule mirrors `DBAutomodWordsRule` — blocked words/phrases (matched
// lowercased). Field order follows `automodWordsSchema`.
type AutomodWordsRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	Words          []string      `bson:"words"           json:"words"`
	MatchSubstring bool          `bson:"match_substring" json:"match_substring"`
}

// AutomodInvitesRule mirrors `DBAutomodInvitesRule` — block Discord invite
// links (with a whitelist of allowed codes). Field order follows
// `automodInvitesSchema`.
type AutomodInvitesRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	AllowedCodes   []string      `bson:"allowed_codes"   json:"allowed_codes"`
}

// AutomodSpamRule mirrors `DBAutomodSpamRule` (v3) — flood de mensajes:
// `max_messages` mensajes del mismo autor dentro de `window_ms`. El conteo vive
// en memoria del módulo.
type AutomodSpamRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	MaxMessages    int           `bson:"max_messages"    json:"max_messages"`
	WindowMs       int           `bson:"window_ms"       json:"window_ms"`
	PurgeBurst     bool          `bson:"purge_burst"     json:"purge_burst"`
}

// AutomodDuplicatesRule mirrors `DBAutomodDuplicatesRule` (v3) — mensajes
// repetidos (el mismo texto una y otra vez) dentro de la ventana.
type AutomodDuplicatesRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	MaxRepeats     int           `bson:"max_repeats"     json:"max_repeats"`
	WindowMs       int           `bson:"window_ms"       json:"window_ms"`
}

// AutomodCapsRule mirrors `DBAutomodCapsRule` (v3) — exceso de MAYÚSCULAS. Los
// mensajes por debajo de `min_length` ni se evalúan.
type AutomodCapsRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	MinLength      int           `bson:"min_length"      json:"min_length"`
	MaxPercent     int           `bson:"max_percent"     json:"max_percent"`
}

// AutomodLinksRule mirrors `DBAutomodLinksRule` (v3) — cualquier URL (complementa
// a `invites`, que sólo mira invitaciones de Discord). Con `block_all` se
// bloquea todo salvo `allowed_domains`; sin él, sólo lo de `blocked_domains`.
type AutomodLinksRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	BlockAll       bool          `bson:"block_all"       json:"block_all"`
	AllowedDomains []string      `bson:"allowed_domains" json:"allowed_domains"`
	BlockedDomains []string      `bson:"blocked_domains" json:"blocked_domains"`
}

// AutomodEmojisRule mirrors `DBAutomodEmojisRule` (v3) — spam de emojis
// (unicode + personalizados del servidor).
type AutomodEmojisRule struct {
	Enabled        bool          `bson:"enabled"         json:"enabled"`
	Action         AutomodAction `bson:"action"          json:"action"`
	TimeoutMs      int           `bson:"timeout_ms"      json:"timeout_ms"`
	ExemptRoles    []string      `bson:"exempt_roles"    json:"exempt_roles"`
	ExemptChannels []string      `bson:"exempt_channels" json:"exempt_channels"`
	CountAsWarn    bool          `bson:"count_as_warn"   json:"count_as_warn"`
	MaxEmojis      int           `bson:"max_emojis"      json:"max_emojis"`
}

// AutomodAttachmentsRule mirrors `DBAutomodAttachmentsRule` (v3) — adjuntos:
// número máximo y extensiones prohibidas (sin punto, en minúsculas).
type AutomodAttachmentsRule struct {
	Enabled           bool          `bson:"enabled"            json:"enabled"`
	Action            AutomodAction `bson:"action"             json:"action"`
	TimeoutMs         int           `bson:"timeout_ms"         json:"timeout_ms"`
	ExemptRoles       []string      `bson:"exempt_roles"       json:"exempt_roles"`
	ExemptChannels    []string      `bson:"exempt_channels"    json:"exempt_channels"`
	CountAsWarn       bool          `bson:"count_as_warn"      json:"count_as_warn"`
	MaxAttachments    int           `bson:"max_attachments"    json:"max_attachments"`
	BlockedExtensions []string      `bson:"blocked_extensions" json:"blocked_extensions"`
}

// ModerationAutomod mirrors `DBModuleModerationAutomod` — the AutoMod ruleset.
// `mentions`/`words`/`invites` son las reglas del v2; el resto llegaron con el
// v3 y se rellenan con sus defaults (regla apagada) en los documentos antiguos.
// Field order follows `automodSchema`.
type ModerationAutomod struct {
	Mentions    AutomodMentionsRule    `bson:"mentions"    json:"mentions"`
	Words       AutomodWordsRule       `bson:"words"       json:"words"`
	Invites     AutomodInvitesRule     `bson:"invites"     json:"invites"`
	Spam        AutomodSpamRule        `bson:"spam"        json:"spam"`
	Duplicates  AutomodDuplicatesRule  `bson:"duplicates"  json:"duplicates"`
	Caps        AutomodCapsRule        `bson:"caps"        json:"caps"`
	Links       AutomodLinksRule       `bson:"links"       json:"links"`
	Emojis      AutomodEmojisRule      `bson:"emojis"      json:"emojis"`
	Attachments AutomodAttachmentsRule `bson:"attachments" json:"attachments"`
}

// ModerationProtection mirrors `DBModuleModerationProtection` (v3) — las
// comprobaciones PREVIAS a cualquier sanción (la red de seguridad del módulo:
// sin ella un moderador puede banear a otro moderador, o a sí mismo). El dueño
// del servidor es SIEMPRE inmune y eso no es configurable.
type ModerationProtection struct {
	ImmuneRoles          []string `bson:"immune_roles"           json:"immune_roles"`
	ImmuneUsers          []string `bson:"immune_users"           json:"immune_users"`
	RespectHierarchy     bool     `bson:"respect_hierarchy"      json:"respect_hierarchy"`
	HierarchyBypassRoles []string `bson:"hierarchy_bypass_roles" json:"hierarchy_bypass_roles"`
	ProtectAdmins        bool     `bson:"protect_admins"         json:"protect_admins"`
	ProtectBots          bool     `bson:"protect_bots"           json:"protect_bots"`
	AllowSelfSanction    bool     `bson:"allow_self_sanction"    json:"allow_self_sanction"`
}

// ModerationEscalationRule mirrors `DBModerationEscalationRule` (v3) — un
// peldaño de la escalera: al llegar a `threshold` infracciones se aplica
// `action` (con `duration_ms` para tempmute/tempban).
type ModerationEscalationRule struct {
	Threshold  int                        `bson:"threshold"   json:"threshold"`
	Action     ModerationEscalationAction `bson:"action"      json:"action"`
	DurationMs int                        `bson:"duration_ms" json:"duration_ms"`
