// resultante también queda registrada.
type ModerationEscalation struct {
	Enabled           bool                       `bson:"enabled"             json:"enabled"`
	WindowMs          int                        `bson:"window_ms"           json:"window_ms"`
	CountTypes        []InfractionCountableType  `bson:"count_types"         json:"count_types"`
	CountAutomod      bool                       `bson:"count_automod"       json:"count_automod"`
	ResetAfterTrigger bool                       `bson:"reset_after_trigger" json:"reset_after_trigger"`
	Rules             []ModerationEscalationRule `bson:"rules"               json:"rules"`
}

// ModerationEffect mirrors `DBModerationEffect` (v3) — un efecto secundario
// configurable: política + valor por defecto de la opción cuando la política es
// `ask`. `Default` mantiene la clave JSON `default` (palabra reservada en Go,
// pero clave normal del documento).
type ModerationEffect struct {
	Policy  ModerationEffectPolicy `bson:"policy"  json:"policy"`
