}

// ModerationEffects mirrors `DBModuleModerationEffects` (v3) — los efectos que
// acompañan a una sanción. Cada uno se puede forzar (`always`), desactivar
// (`never`) o dejar a decisión del moderador (`ask`).
type ModerationEffects struct {
	VoiceDisconnectOnMute ModerationEffect `bson:"voice_disconnect_on_mute" json:"voice_disconnect_on_mute"`
	ServerMuteOnMute      ModerationEffect `bson:"server_mute_on_mute"      json:"server_mute_on_mute"`
	StripRolesOnMute      ModerationEffect `bson:"strip_roles_on_mute"      json:"strip_roles_on_mute"`
	PurgeOnBan            ModerationEffect `bson:"purge_on_ban"             json:"purge_on_ban"`
	PurgeOnBanSeconds     int              `bson:"purge_on_ban_seconds"     json:"purge_on_ban_seconds"`
	PurgeOnKick           ModerationEffect `bson:"purge_on_kick"            json:"purge_on_kick"`
	PurgeOnKickSeconds    int              `bson:"purge_on_kick_seconds"    json:"purge_on_kick_seconds"`
	DeleteInvocation      bool             `bson:"delete_invocation"        json:"delete_invocation"`
	EphemeralReplies      bool             `bson:"ephemeral_replies"        json:"ephemeral_replies"`
