// ── Normalización ───────────────────────────────────────────────────────────

// NormalizeModeration backfills every collection field that decoded as `nil`
// (from a partial Mongo doc or a legacy cache entry) with a non-nil empty
// value, mirroring the zod `.default([])` / `.default({})`. This keeps the JSON
// body emitting `[]` / `{}` instead of `null` — the exact shape the Node
// service produces after re-parsing through `moduleModerationSchema`.
//
// Scalars and nullable pointers are left untouched: a stored `null` stays
// `null`, matching the `string | null` fields (`log_channel_id`, `mute.role_id`,
// each command's `dm_embed.color`, los `alert_*` del v3). Idempotent.
//
// OJO: normalizar NO es migrar. Aquí sólo se rellenan colecciones vacías; los
// defaults NO-cero del v3 (`timeout_ms`, ventanas, umbrales) los pone
// `MigrateModerationRaw`.
func NormalizeModeration(m *ModuleModeration) {
	if m == nil {
		return
	}

	normalizeModerationAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]ModerationCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeModerationAccess(&v.Access)
			v.Aliases = ensureModerationStrSlice(v.Aliases)
			m.Commands[k] = v
		}
	}

	m.Automod.Mentions.ExemptRoles = ensureModerationStrSlice(m.Automod.Mentions.ExemptRoles)
	m.Automod.Mentions.ExemptChannels = ensureModerationStrSlice(m.Automod.Mentions.ExemptChannels)
	m.Automod.Mentions.BlockedUsers = ensureModerationStrSlice(m.Automod.Mentions.BlockedUsers)
	m.Automod.Mentions.BlockedRoles = ensureModerationStrSlice(m.Automod.Mentions.BlockedRoles)

	m.Automod.Words.ExemptRoles = ensureModerationStrSlice(m.Automod.Words.ExemptRoles)
	m.Automod.Words.ExemptChannels = ensureModerationStrSlice(m.Automod.Words.ExemptChannels)
	m.Automod.Words.Words = ensureModerationStrSlice(m.Automod.Words.Words)

	m.Automod.Invites.ExemptRoles = ensureModerationStrSlice(m.Automod.Invites.ExemptRoles)
	m.Automod.Invites.ExemptChannels = ensureModerationStrSlice(m.Automod.Invites.ExemptChannels)
	m.Automod.Invites.AllowedCodes = ensureModerationStrSlice(m.Automod.Invites.AllowedCodes)

	// v3: las seis reglas nuevas.
	m.Automod.Spam.ExemptRoles = ensureModerationStrSlice(m.Automod.Spam.ExemptRoles)
	m.Automod.Spam.ExemptChannels = ensureModerationStrSlice(m.Automod.Spam.ExemptChannels)

	m.Automod.Duplicates.ExemptRoles = ensureModerationStrSlice(m.Automod.Duplicates.ExemptRoles)
	m.Automod.Duplicates.ExemptChannels = ensureModerationStrSlice(m.Automod.Duplicates.ExemptChannels)

	m.Automod.Caps.ExemptRoles = ensureModerationStrSlice(m.Automod.Caps.ExemptRoles)
	m.Automod.Caps.ExemptChannels = ensureModerationStrSlice(m.Automod.Caps.ExemptChannels)

	m.Automod.Links.ExemptRoles = ensureModerationStrSlice(m.Automod.Links.ExemptRoles)
	m.Automod.Links.ExemptChannels = ensureModerationStrSlice(m.Automod.Links.ExemptChannels)
	m.Automod.Links.AllowedDomains = ensureModerationStrSlice(m.Automod.Links.AllowedDomains)
	m.Automod.Links.BlockedDomains = ensureModerationStrSlice(m.Automod.Links.BlockedDomains)

	m.Automod.Emojis.ExemptRoles = ensureModerationStrSlice(m.Automod.Emojis.ExemptRoles)
	m.Automod.Emojis.ExemptChannels = ensureModerationStrSlice(m.Automod.Emojis.ExemptChannels)

	m.Automod.Attachments.ExemptRoles = ensureModerationStrSlice(m.Automod.Attachments.ExemptRoles)
	m.Automod.Attachments.ExemptChannels = ensureModerationStrSlice(m.Automod.Attachments.ExemptChannels)
	m.Automod.Attachments.BlockedExtensions = ensureModerationStrSlice(m.Automod.Attachments.BlockedExtensions)

	// v3: bloques nuevos de nivel superior.
	m.Protection.ImmuneRoles = ensureModerationStrSlice(m.Protection.ImmuneRoles)
	m.Protection.ImmuneUsers = ensureModerationStrSlice(m.Protection.ImmuneUsers)
	m.Protection.HierarchyBypassRoles = ensureModerationStrSlice(m.Protection.HierarchyBypassRoles)

	if m.Escalation.CountTypes == nil {
		m.Escalation.CountTypes = []InfractionCountableType{}
	}
	if m.Escalation.Rules == nil {
		m.Escalation.Rules = []ModerationEscalationRule{}
	}

	m.Raid.LockdownChannels = ensureModerationStrSlice(m.Raid.LockdownChannels)

	m.Gate.BlockedNamePatterns = ensureModerationStrSlice(m.Gate.BlockedNamePatterns)

	m.Antinuke.TrustedUsers = ensureModerationStrSlice(m.Antinuke.TrustedUsers)
	m.Antinuke.TrustedRoles = ensureModerationStrSlice(m.Antinuke.TrustedRoles)
	if m.Antinuke.Limits == nil {
		m.Antinuke.Limits = map[string]ModerationNukeLimit{}
	}

	m.Lockdown.BypassRoles = ensureModerationStrSlice(m.Lockdown.BypassRoles)
	m.Lockdown.ServerChannels = ensureModerationStrSlice(m.Lockdown.ServerChannels)

	// v4: `flows` — mismo patrón que NormalizeAutomation: la colección nil → [],
	// y aplanado de bson.D/M/A dentro de los `params` libres del trigger, las
	// condiciones y los pasos (setup/steps/branch.steps). `Branches` es la
	// única excepción de colección: ausente (nil) es un estado legítimo («sin
	// ramas»), igual que en Automation — nunca se fuerza a `[]`.
	if m.Flows == nil {
		m.Flows = []ModerationFlow{}
	}
	for i := range m.Flows {
		f := &m.Flows[i]
		if f.Setup == nil {
			f.Setup = []ModerationFlowStep{}
		}
		if f.Conditions == nil {
			f.Conditions = []ModerationFlowCondition{}
		}
		if f.Steps == nil {
			f.Steps = []ModerationFlowStep{}
		}
		f.Scope.Channels.IDs = ensureModerationStrSlice(f.Scope.Channels.IDs)
		f.Scope.Categories.IDs = ensureModerationStrSlice(f.Scope.Categories.IDs)
		f.Scope.Roles.IDs = ensureModerationStrSlice(f.Scope.Roles.IDs)
		f.Trigger.Params = normalizeParams(f.Trigger.Params)
		for j := range f.Setup {
			f.Setup[j].Params = normalizeParams(f.Setup[j].Params)
		}
		for j := range f.Conditions {
			f.Conditions[j].Params = normalizeParams(f.Conditions[j].Params)
		}
		for j := range f.Steps {
			f.Steps[j].Params = normalizeParams(f.Steps[j].Params)
		}
		for j := range f.Branches {
			b := &f.Branches[j]
			if b.Conditions == nil {
				b.Conditions = []ModerationFlowCondition{}
			}
			if b.Steps == nil {
				b.Steps = []ModerationFlowStep{}
			}
			for k := range b.Conditions {
				b.Conditions[k].Params = normalizeParams(b.Conditions[k].Params)
			}
			for k := range b.Steps {
				b.Steps[k].Params = normalizeParams(b.Steps[k].Params)
			}
		}
	}
}

// normalizeModerationAccess backfills the three access-list ID slices of a
// command-access block so each serialises as `[]`.
func normalizeModerationAccess(a *ModerationCommandAccess) {
	a.Roles.IDs = ensureModerationStrSlice(a.Roles.IDs)
	a.Channels.IDs = ensureModerationStrSlice(a.Channels.IDs)
	a.Categories.IDs = ensureModerationStrSlice(a.Categories.IDs)
}

func ensureModerationStrSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// ── Migración ───────────────────────────────────────────────────────────────

// ModerationRawSchemaVersion lee `schema_version` de un subdoc crudo (lean) de
// `module_moderation`, tolerando las formas int/int32/int64/float64 que
// producen los decoders de BSON y de JSON. Devuelve 0 cuando falta — el repo
// trata un subdoc sin versión como "aplica los defaults completos". Espejo de
// TempvoiceRawSchemaVersion.
func ModerationRawSchemaVersion(raw bson.M) int {
	switch v := raw["schema_version"].(type) {
	case int:
		return v
	case int32:
		return int(v)
	case int64:
		return int(v)
	case float64:
		return int(v)
	}
	return 0
}

// MigrateModerationRaw sube un subdoc crudo (POJO lean) de `module_moderation`
// a la forma tipada actual, rellenando con sus defaults TODO bloque del v3 que
// el documento NO traiga.
//
// Existe por la misma razón que MigrateTempvoiceRaw, pero con una diferencia
// clave: el repo decodifica directo al struct, así que un documento v2 —que no
// tiene `protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
// `lockdown` ni las seis reglas nuevas de automod— saldría con TODO a cero.
// Y los defaults del v3 NO son valores cero: `timeout_ms` (300000), las
// ventanas (`window_ms`, `join_window_ms`), los umbrales (`join_threshold`,
// `max_messages`…) y las protecciones que nacen activas. Sin este relleno un
// servidor que ya existía vería el anti-raid con umbral 0 y ventana 0 en cuanto
// lo activara.
//
// A propósito NO hay early-return por `schema_version`: ese atajo es el
// "veneno" documentado que rompió tempvoice —una escritura puede haber sellado
// la versión actual sobre una forma sin migrar— así que la migración se ejecuta
// SIEMPRE. Es barata e idempotente.
//
// La ausencia se detecta mirando la CLAVE en el `bson.M` crudo, no el valor
// cero del struct: así, si alguien pone a 0 un umbral a propósito desde la
// dashboard, su valor no se pisa en la siguiente lectura. Un valor presente
// pero que no es un sub-documento (`null`, un escalar suelto) cuenta como
// ausente: no hay nada que conservar.
//
// Termina estampando la versión actual.
func MigrateModerationRaw(raw bson.M) ModuleModeration {
	var m ModuleModeration
	if b, err := bson.Marshal(raw); err == nil {
		_ = bson.Unmarshal(b, &m)
	}

	// Un documento sin `command_mode` (o con basura) cae en "both", igual que
	// hace tempvoice. La cadena vacía no es un modo válido, así que no se pisa
	// ninguna elección real.
	if m.CommandMode == "" {
		m.CommandMode = ModerationCommandModeBoth
	}

	// Comandos: se conserva la config de los que ya estén y se siembran los que
	// falten (los 11 del v3 en un documento v2). El default es "activo +
	// hereda el acceso global", así que sembrarlos no restringe nada.
	if m.Commands == nil {
		m.Commands = map[string]ModerationCommand{}
	}
	for _, name := range ModerationCommandNames {
		if _, ok := m.Commands[name]; !ok {
			m.Commands[name] = ModerationCommandDefault()
		}
	}

	migrateModerationAutomodRaw(raw, &m)

	if !moderationRawBlock(raw, "protection") {
		m.Protection = DefaultModerationProtection()
	}
	if !moderationRawBlock(raw, "escalation") {
		m.Escalation = DefaultModerationEscalation()
	}
	if !moderationRawBlock(raw, "effects") {
		m.Effects = DefaultModerationEffects()
	}
	if !moderationRawBlock(raw, "raid") {
		m.Raid = DefaultModerationRaid()
	}
	if !moderationRawBlock(raw, "gate") {
		m.Gate = DefaultModerationGate()
	}
	if !moderationRawBlock(raw, "lockdown") {
		m.Lockdown = DefaultModerationLockdown()
	}
	migrateModerationAntinukeRaw(raw, &m)

	m.SchemaVersion = SchemaVersionModeration
	return m
}

// migrateModerationAutomodRaw rellena el bloque `automod`: entero si falta, o
// regla a regla si está pero le faltan claves (las seis del v3 en un documento
// v2). Cada regla se mira por su clave en el crudo, nunca por su valor cero.
func migrateModerationAutomodRaw(raw bson.M, m *ModuleModeration) {
	automod, ok := asModerationRawMap(raw["automod"])
	if !ok {
		m.Automod = DefaultModerationAutomod()
		return
	}
	if _, ok := automod["mentions"]; !ok {
		m.Automod.Mentions = DefaultAutomodMentionsRule()
	}
	if _, ok := automod["words"]; !ok {
		m.Automod.Words = DefaultAutomodWordsRule()
	}
	if _, ok := automod["invites"]; !ok {
		m.Automod.Invites = DefaultAutomodInvitesRule()
	}
	if _, ok := automod["spam"]; !ok {
		m.Automod.Spam = DefaultAutomodSpamRule()
	}
	if _, ok := automod["duplicates"]; !ok {
		m.Automod.Duplicates = DefaultAutomodDuplicatesRule()
	}
	if _, ok := automod["caps"]; !ok {
		m.Automod.Caps = DefaultAutomodCapsRule()
	}
	if _, ok := automod["links"]; !ok {
		m.Automod.Links = DefaultAutomodLinksRule()
	}
	if _, ok := automod["emojis"]; !ok {
		m.Automod.Emojis = DefaultAutomodEmojisRule()
	}
	if _, ok := automod["attachments"]; !ok {
		m.Automod.Attachments = DefaultAutomodAttachmentsRule()
	}
}

// migrateModerationAntinukeRaw rellena `antinuke`: entero si falta, o sólo los
// límites que falten si el bloque ya existe (una acción vigilada nueva en una
// versión futura entra por aquí sin pisar los topes que el servidor ya haya
// ajustado).
func migrateModerationAntinukeRaw(raw bson.M, m *ModuleModeration) {
	antinuke, ok := asModerationRawMap(raw["antinuke"])
	if !ok {
		m.Antinuke = DefaultModerationAntinuke()
		return
	}
	if m.Antinuke.Punishment == "" {
		m.Antinuke.Punishment = ModerationNukePunishStripRoles
	}
	if _, ok := antinuke["limits"]; !ok {
		m.Antinuke.Limits = DefaultModerationNukeLimits()
		return
	}
	if m.Antinuke.Limits == nil {
		m.Antinuke.Limits = map[string]ModerationNukeLimit{}
	}
	for action, def := range DefaultModerationNukeLimits() {
		if _, ok := m.Antinuke.Limits[action]; !ok {
			m.Antinuke.Limits[action] = def
		}
	}
}

// moderationRawBlock indica si el subdoc crudo trae `key` como sub-documento.
// Un `null`, un escalar o un tipo inesperado cuentan como AUSENTE: no hay
// configuración que conservar y el default es lo correcto.
func moderationRawBlock(raw bson.M, key string) bool {
	_, ok := asModerationRawMap(raw[key])
	return ok
}

// asModerationRawMap acepta las tres formas en las que puede llegar un
// sub-documento anidado. La tercera es la importante: el driver de Mongo v2
// decodifica TODO documento anidado dentro de un `bson.M` como `bson.D` (el
// mecanismo de "ancestor" del v1, que propagaba `bson.M` hacia abajo,
// desapareció). Con el `asBsonMap` genérico —que sólo mira `bson.M` y
// `map[string]any`— la migración creería que el bloque no existe y lo pisaría
// con los defaults en CADA lectura, borrando la configuración del servidor.
func asModerationRawMap(v any) (bson.M, bool) {
	switch m := v.(type) {
	case bson.M:
		return m, true
	case map[string]any:
		return bson.M(m), true
	case bson.D:
		out := make(bson.M, len(m))
		for _, e := range m {
			out[e.Key] = e.Value
		}
		return out, true
	}
	return nil, false
}
